def lexicographicallySmallestString(s: str) -> str:
    n = len(s)

    def consecutive(a, b):
        d = abs(ord(a) - ord(b))
        return d == 1 or d == 25  # circular: 'a' and 'z'

    # can[i][j]: substring s[i:j] can be removed completely
    can = [[False] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        can[i][i] = True
    for length in range(2, n + 1, 2):
        for i in range(0, n - length + 1):
            j = i + length
            for k in range(i + 1, j, 2):  # partner of s[i]
                if consecutive(s[i], s[k]) and can[i + 1][k] and can[k + 1][j]:
                    can[i][j] = True
                    break

    # dp[i]: smallest string obtainable from s[i:]
    dp = [""] * (n + 1)
    for i in range(n - 1, -1, -1):
        best = s[i] + dp[i + 1]
        for j in range(i + 2, n + 1, 2):
            if can[i][j] and dp[j] < best:
                best = dp[j]
        dp[i] = best
    return dp[0]
